@Entry
@Component
struct AuditPanel {
  @State auditTrail: string = '';

  appendAudit(message: string): void {
    this.auditTrail += message;
  }

  build() {
    Column() {
      Text('Audit controls')
      Button('Record')
    }
  }
}

